 auto router=server1_http_router_create();server1::http::mountDownloadRoutes(router,&manager,"");route(router,"/test/downloader/getAll",404);server1::http::mountDownloadRoutes(router,&manager,"test");
 check(route(router,"/test/downloader/add",500)["error"].toObject()["code"]==1,"missing URL code");check(route(router,"/test/downloader/get",500)["error"].toObject()["message"]=="missing id","missing id");
 for(auto op:{"get","pause","resume","remove","stream"})route(router,QString("/test/downloader/%1?id=absent").arg(op),500);
 auto initial=manager.add(fixture.url());auto id=initial["id"].toString();check(initial["status"]=="running"&&initial["downloaded"]==0&&!initial.contains("fileName"),"initial stats");
 check(until([&]{return manager.get(id)["status"]=="finished";}),"download finish");auto done=manager.get(id);check(done["downloaded"].toInteger()==fixture.data.size()&&done["progress"]==100,"download stats");check(done["speed"].toInteger()==fixture.data.size(),"terminal speed");check(read(manager.filePath(id))==fixture.data,"file content");check(QJsonDocument::fromJson(read(dir.path()+"/downManager.json")).object().contains(id),"completion persists");
 stream(router,id,{},200,fixture.data);stream(router,id,"bytes=2-5",206,fixture.data.mid(2,4));stream(router,id,"bytes=-7",206,fixture.data.right(7));stream(router,id,"bytes=131070-",206,fixture.data.right(2));stream(router,id,"bytes=999999-",416,{});stream(router,id,"bytes=0-999999",416,{});stream(router,id,"bytes=wat-wat",500,{});
 auto duplicate=manager.add(fixture.url())["id"].toString();check(until([&]{return manager.get(duplicate)["status"]=="finished";}),"duplicate finish");check(manager.get(duplicate)["fileName"]=="payload (1).bin","rename collision");
 auto slow=manager.add(fixture.url("/slow"))["id"].toString();check(until([&]{return fixture.requests.size()>=3&&QFileInfo(dir.path()+"/downloads/payload (2).bin").size()>0;}),"partial bytes");check(manager.pause(slow).isEmpty(),"pause");check(manager.get(slow)["status"]=="paused","paused state");check(manager.resume(slow).isEmpty(),"resume");check(until([&]{return manager.get(slow)["status"]=="finished";}),"resume finish");check(read(manager.filePath(slow))==fixture.data,"resume bytes");check(fixture.requests.last().toLower().contains("range: bytes=32768-"),"resume range");
 auto early=manager.add(fixture.url("/slow"))["id"].toString();check(manager.pause(early).isEmpty(),"pause before init");check(manager.remove(early).isEmpty(),"remove before init");QCoreApplication::processEvents();check(manager.get(early).isEmpty(),"removed callback not resurrected");
 auto fail=manager.add(fixture.url("/fail"))["id"].toString();check(until([&]{return manager.get(fail)["status"]=="error";}),"404 error");check(manager.get(fail)["error"]=="Response status was 404","404 message");
 {DownloadManager restored(dir.path());check(restored.get(id)["status"]=="finished","finished restore");check(restored.all().size()>=3,"restore all");}
 check(manager.remove(id).isEmpty(),"remove finished");check(!QFile::exists(dir.path()+"/downloads/payload.bin"),"remove file");check(QJsonDocument::fromJson(read(dir.path()+"/downManager.json")).object().contains(id),"source does not persist remove eagerly");
 server1_http_router_destroy(router);
 QTemporaryDir restart;QDir().mkdir(restart.path()+"/downloads");write(restart.path()+"/downloads/part.bin",fixture.data.left(32768));
 QJsonObject record{{"id","restore"},{"url",fixture.url()},{"status","running"},{"fileName","part.bin"},{"total",fixture.data.size()},{"downloaded",32768},{"progress",25}};write(restart.path()+"/downManager.json",QJsonDocument(QJsonObject{{"restore",record},{"missing",QJsonObject{{"id","missing"},{"downloaded",1},{"fileName","absent"},{"status","finished"}}}}).toJson());
 {DownloadManager restored(restart.path());check(restored.get("missing").isEmpty(),"missing file prune");check(until([&]{return restored.get("restore")["status"]=="finished";}),"resume on construction without routes");check(read(restored.filePath("restore"))==fixture.data,"restored bytes");}
 record["status"]="paused";record["id"]="paused";write(restart.path()+"/downManager.json",QJsonDocument(QJsonObject{{"paused",record}}).toJson());
 {DownloadManager restored(restart.path());check(restored.pause("paused")=="there is no download handler with this id","restored paused has no handler");check(restored.resume("paused").isEmpty(),"restored pause restart");check(until([&]{return restored.get("paused")["status"]=="finished";}),"restored pause finish");check(!fixture.requests.last().toLower().contains("range:"),"restored pause restarts rather than resumes");}
 auto redirect=manager.add(fixture.url("/redirect"))["id"].toString();check(until([&]{return manager.get(redirect)["status"]=="finished";}),"redirect finishes");check(read(manager.filePath(redirect))==fixture.data,"redirect bytes");
 auto beforeFiles=QDir(dir.path()+"/downloads").entryList(QDir::Files);QString timerFile;auto timerId=manager.add(fixture.url("/slow"))["id"].toString();check(until([&]{for(auto f:QDir(dir.path()+"/downloads").entryList(QDir::Files)){if(!beforeFiles.contains(f)&&QFileInfo(dir.path()+"/downloads/"+f).size()>0){timerFile=dir.path()+"/downloads/"+f;return true;}}return false;}),"timer partial file");check(manager.pause(timerId).isEmpty(),"pause timer transfer");check(until([&]{return manager.get(timerId)["downloaded"].toInteger()>0;},3000),"two-second stat tick");auto persisted=QJsonDocument::fromJson(read(dir.path()+"/downManager.json")).object()[timerId].toObject();check(persisted["status"]=="paused"&&persisted["downloaded"].toInteger()==32768,"pause persisted by stats interval");check(manager.remove(timerId).isEmpty(),"remove paused");check(!QFile::exists(timerFile),"remove paused partial file");
 {QTemporaryDir stop;auto owned=std::make_unique<DownloadManager>(stop.path());auto id=owned->add(fixture.url("/slow"))["id"].toString();check(until([&]{return QFileInfo(stop.path()+"/downloads/payload.bin").size()>0;}),"teardown partial file");owned.reset();QCoreApplication::processEvents();check(QFile::exists(stop.path()+"/downloads/payload.bin"),"teardown retains partial file");}
 {QTemporaryDir concurrent;Fixture f;DownloadManager m(concurrent.path());for(int i=0;i<8;++i)m.add(f.url("/held"));check(until([&]{return f.requests.size()==8;},700),"source has no six-download per-host queue");}
 QTemporaryDir ordered;write(ordered.path()+"/downManager.json",R"({"z":{"id":"z"},"a":{"id":"a"}})");{DownloadManager m(ordered.path());check(m.all().at(0).toObject()["id"]=="z","restore object insertion order");}
 std::cout<<"PASS N07 lifecycle, routes, localhost transfer, range, persistence restart\n";return 0;
